import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./TimePicker.stories";
import TimePicker from ".";

const { Period } = composeStories(stories) as any;

describe("TimePicker component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Period />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<TimePicker data-testid="timepicker" />);
    expect(screen.getByTestId("timepicker")).not.toBeNull();
  });

  it("invalidate 24h input format", async () => {
    const onChange = jest.fn();
    render(<TimePicker onChange={onChange} />);
    const input = screen.getByRole("textbox");

    // wrong time input
    await userEvent.type(input, "25:00");
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(0);
    expect(input).toHaveAttribute("aria-invalid", "true");

    // clear
    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith("");

    // correct time input
    await userEvent.type(input, "22:00");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith("22:00");
    expect(input).not.toHaveAttribute("aria-invalid", "true");
  });

  it("invalidate 12h input format", async () => {
    consoleSpy.log.mockRestore();

    const onChange = jest.fn();
    render(<TimePicker onChange={onChange} use12Hours />);
    const input = screen.getAllByRole("textbox")[0];
    const periodButton = screen.getByRole("button", { name: /toggle menu/i });

    // wrong time input
    await userEvent.type(input, "13:00");
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(0);
    expect(input).toHaveAttribute("aria-invalid", "true");

    // clear
    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith("");

    // correct time input
    await userEvent.type(input, "12:00");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith("12:00 am");
    expect(input).not.toHaveAttribute("aria-invalid", "true");

    // change to PM
    fireEvent.click(periodButton);
    expect(screen.getByRole("listbox")).toBeInTheDocument();
    fireEvent.click(screen.getByRole("option", { name: "PM" }));
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith("12:00 pm");
  });

  it("updates input string from any cursor position #1360", async () => {
    const onChange = jest.fn();
    render(<TimePicker onChange={onChange} />);

    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;
    await userEvent.type(input, "1015");
    expect(input).toHaveValue("10:15");
    expect(input.selectionStart).toEqual(5);

    input.setSelectionRange(0, 0);
    await userEvent.type(input, "1112", {
      initialSelectionStart: 0,
      initialSelectionEnd: 0,
    });
    expect(input.selectionStart).toEqual(5);
    expect(input).toHaveValue("11:12");

    input.setSelectionRange(2, 2);
    await userEvent.type(input, "20", {
      initialSelectionStart: 2,
      initialSelectionEnd: 2,
    });
    expect(input.selectionStart).toEqual(5);
    expect(input).toHaveValue("11:20");
  });

  it("allow controlled mode", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <TimePicker onChange={onChange} value="10:10" />
    );
    const input = screen.getByRole("textbox");
    expect(input).toHaveValue("10:10");
    expect(onChange).not.toHaveBeenCalled();

    rerender(<TimePicker onChange={onChange} value="12:12" />);
    expect(input).toHaveValue("12:12");
    expect(onChange).not.toHaveBeenCalled();

    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith("");

    await userEvent.type(input, "11:11");
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(5);
    expect(onChange).toHaveBeenLastCalledWith("11:11");
  });

  it("dispatch validation state", async () => {
    const onValidation = jest.fn();
    render(<TimePicker onValidation={onValidation} />);
    const input = screen.getByRole("textbox");
    await userEvent.type(input, "55:55");
    fireEvent.blur(input);
    expect(onValidation).toHaveBeenCalledTimes(1);
    expect(onValidation).toHaveBeenLastCalledWith(false);

    await userEvent.clear(input);
    expect(onValidation).toHaveBeenCalledTimes(2);
    expect(onValidation).toHaveBeenLastCalledWith(true);
  });

  it("allow controlled mode with period", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <TimePicker onChange={onChange} value="10:10 am" use12Hours />
    );
    const input = screen.getAllByRole("textbox")[0];
    expect(input).toHaveValue("10:10");

    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith("");

    await userEvent.type(input, "1220");
    expect(input).toHaveValue("12:20");
    expect(onChange).toHaveBeenCalledTimes(5);
    expect(onChange).toHaveBeenLastCalledWith("12:20 am");
    expect(input).not.toHaveAttribute("aria-invalid", "true");

    rerender(<TimePicker onChange={onChange} value="11:12 pm" use12Hours />);
    expect(onChange).toHaveBeenCalledTimes(5); //no called again, as component is rerendered

    const periodButton = screen.getByRole("button", { name: /toggle menu/i });
    fireEvent.click(periodButton);
    expect(screen.getByRole("listbox")).toBeInTheDocument();
    fireEvent.click(screen.getByRole("option", { name: "AM" }));

    expect(input).toHaveValue("11:12");
    expect(onChange).toHaveBeenLastCalledWith("11:12 am");
  });
});
